// lint-staged.config.js
// Handles files with brackets in paths (e.g., Next.js [id] routes)

import { readFileSync, renameSync, writeFileSync } from "node:fs";
import path from "node:path";
import { execGit } from "./scripts/exec-git.ts";

// ISS-7383/ISS-7396. FEA-1859 wrote this guard against
// `packages/api/src/session-trace/derivation.ts` and a test file FEA-3568
// (#3306) later deleted, so it failed on file-not-found for anyone who staged a
// surviving trigger. ISS-7403 (#5551) unblocked that by pointing the command at
// `packaging-workspace-deps.test.ts` — a file that exists, but one carrying none
// of the assertions the deleted test made, while the glob still named a
// `packages/api` path FEA-3568 had moved to `packages/lib`. A guard that runs,
// exits 0 and states nothing about its subject is the failure ISS-7395 is about,
// so both halves are repointed at what the contract lives on TODAY: the
// derivation module in its `packages/lib` home, the desktop module that imports
// it, and the packaging closure that must keep both bundled from source. The
// assertions themselves are restored in the invoked test.
//
// `pnpm -C packages/api build` went with them: it existed because FEA-1859's
// contract was about the BUILT `@repo/api` output, and `@repo/lib` — the
// derivation helper's home since FEA-3568 — declares no `build` script, `main`,
// or `exports`, so there is no built artifact for this guard to produce.
//
// ISS-11262 converted the invoked suite to Vitest, so it runs through the
// desktop node Vitest config rather than `tsx --test`.
const SESSION_TRACE_RUNTIME_IMPORT_GUARD = [
  "pnpm -C apps/desktop exec vitest run --config vitest.node.config.ts test/packaging-workspace-deps.test.ts",
];
const DESKTOP_AGENT_DASHBOARD_BOUNDARY_GUARD = [
  "pnpm -C apps/desktop run assert:design-system-boundary",
];

export default {
  // `lint-staged.config.js` is deliberately NOT a trigger here (ISS-7396). It is
  // not a subject of the session-trace contract, and a self-referential glob is
  // what made this config unrepairable without `--no-verify` — the repairing
  // commit ran the broken guard. Every path this file names is instead swept by
  // scripts/lint/lint-staged-guard-targets.test.ts (DELETED by ISS-10525 — no longer runs), in the PR `lint-scripts`
  // lane; that lane is path-filtered, so this file is listed in pr-test.yml's
  // `lint_scripts` filter and pinned there by lint-scripts-gate.test.ts.
  // `vite.main.config.ts` is a trigger because it is the SOURCE OF TRUTH
  // for which workspace packages are bundled from source (review finding). The
  // guard reads its `WORKSPACE_INLINE` array, so a config-only change that
  // stops inlining `@repo/lib` is exactly the edit that must run this check —
  // and before it was listed, that edit touched none of the other triggers.
  // `vite.preload.config.ts` is listed for the same reason (ISS-10357): it is
  // the second consumer of that array, so a preload-only edit that stops
  // inlining is the same edit wearing a different filename.
  "{packages/lib/session-trace/derivation.ts,apps/desktop/src/main/database/session-trace.ts,apps/desktop/vite.main.config.ts,apps/desktop/vite.preload.config.ts,apps/desktop/scripts/packaging-workspace-deps.mjs,apps/desktop/test/packaging-workspace-deps.test.ts}":
    () => SESSION_TRACE_RUNTIME_IMPORT_GUARD,
  "{apps/desktop/src/main/**/*.{ts,tsx},apps/desktop/src/server/**/*.{ts,tsx},apps/desktop/src/shared/**/*.{ts,tsx},apps/desktop/scripts/dependency-cruiser.config.cjs,lint-staged.config.js}":
    () => DESKTOP_AGENT_DASHBOARD_BOUNDARY_GUARD,
  // ISS-9232: the top-level `project`/`types` domains make every Biome run scan
  // the whole repo (~42 CPU-s, ~5 GB), but only apps/desktop uses them
  // (FEA-1544) and biome.jsonc already turns them off everywhere else. So other
  // files are checked against a copy with those two domains off, which reports
  // the same findings without the scan. scripts/commit-checks.sh passes
  // `--continue-on-error` so both commands run when the first one fails.
  "*.{js,jsx,ts,tsx,json,jsonc}": (filenames) => {
    const desktop = filenames.filter(isDesktopPath);
    const rest = filenames.filter((f) => !isDesktopPath(f));
    const commands = [];
    if (rest.length > 0) {
      writeNoScanBiomeConfig();
      commands.push(
        biomeCheck(`--config-path "${NO_SCAN_BIOME_CONFIG}" `, rest)
      );
    }
    if (desktop.length > 0) {
      commands.push(biomeCheck("", desktop));
    }
    return commands;
  },
};

const ROOT = import.meta.dirname;
const DESKTOP_PREFIX = `apps${path.sep}desktop${path.sep}`;
const BIOME_CONFIG = path.join(ROOT, "biome.jsonc");
// Generated, gitignored. It must sit beside biome.jsonc: its relative paths
// (`./biome-plugins/*.grit`, `files.includes`) resolve against its own folder.
export const NO_SCAN_BIOME_CONFIG = path.join(ROOT, ".biome-noscan.jsonc");
const TOP_LEVEL_DOMAINS = /^( {2}"linter": \{\r?\n {4}"domains": \{)([^}]*)\}/m;
const SCANNING_DOMAIN = /"(project|types)": "[^"]*"/g;

const isDesktopPath = (f) =>
  path.relative(ROOT, path.resolve(ROOT, f)).startsWith(DESKTOP_PREFIX);

// Quote each path to handle brackets (biome interprets [] as glob patterns)
// --no-errors-on-unmatched: Don't error when files are ignored by biome.jsonc
// --error-on-warnings: a warning fails the commit, as it fails `pnpm lint` (ISS-12116)
// ISS-7204: `pnpm exec`, never a registry runner. npm's registry carries an
// unrelated package named `biome`, and `npx`/`pnpm dlx`/`yarn dlx`/`bunx`/
// `npm exec` all fall back to installing it whenever no local biome bin is
// reachable — it exits 0 without checking anything, so this hook would pass
// silently on files Biome would have rejected. This prefix is pinned
// positively by lint-changed-gate-contract.test.ts and
// lint-staged-biome-no-scan.test.ts.
const biomeCheck = (configFlag, files) =>
  `pnpm exec biome check ${configFlag}--write --no-errors-on-unmatched --error-on-warnings ${files.map((f) => `"${f}"`).join(" ")}`;

// lint-staged builds these commands before it hides the unstaged hunks of
// partially staged files, and Biome runs after, so a staged biome.jsonc is
// read from the index: that is the version Biome will see. Whether it is
// staged comes from git, not the rule's file list: lint-staged calls the rule
// once per chunk of that list (runAll.js chunkFiles), every chunk writes this
// file, and the last chunk need not hold biome.jsonc. The rename keeps a
// concurrent reader from seeing a half-written file.
export const writeNoScanBiomeConfig = (target = NO_SCAN_BIOME_CONFIG) => {
  const biomeJsonc = execGit(
    ["diff", "--cached", "--name-only", "--", "biome.jsonc"],
    { cwd: ROOT }
  )
    ? execGit(["show", ":biome.jsonc"], { cwd: ROOT })
    : readFileSync(BIOME_CONFIG, "utf8");
  const partial = `${target}.${process.pid}`;
  writeFileSync(partial, noScanBiomeConfig(biomeJsonc));
  renameSync(partial, target);
};

export const noScanBiomeConfig = (biomeJsonc) => {
  if (!TOP_LEVEL_DOMAINS.test(biomeJsonc)) {
    throw new Error(
      `lint-staged.config.js cannot build ${NO_SCAN_BIOME_CONFIG}: biome.jsonc no longer opens its "linter" block with "domains". Update TOP_LEVEL_DOMAINS to match it.`
    );
  }
  return biomeJsonc.replace(
    TOP_LEVEL_DOMAINS,
    (_, open, body) =>
      `${open}${body.replace(SCANNING_DOMAIN, '"$1": "none"')}}`
  );
};
